sys_script_include.script:
var getSwiftPosDataUIAction = Class.create();
getSwiftPosDataUIAction.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    SwiftDataForTrade: function() {
        try {
            var sysidTrade = this.getParameter("sysparm_id");
            var attributeTrade = this.getParameter("sysparm_attribute_sync");
            var sourceSystem = this.getParameter("sysparm_source");

            if (attributeTrade == "Attribute Sync is in progress") {
                return "Attribute Sync is in progress";
            }
            var TradeRecord = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
            TradeRecord.addQuery("sys_id", sysidTrade);
            TradeRecord.query();
            if (TradeRecord.next()) {
                if (sourceSystem == "GHSS" || sourceSystem == "GCS") {//Added gcs as part of GR11 P2 

                    gs.eventQueue('x_hsb11_mss_c_proc.el_custody_swift_comp', TradeRecord);
                    TradeRecord.swift_attribute_sync = "Attribute Sync is in progress";
                    TradeRecord.update();
                    return "queueTriggered";

                } else {
                    gs.eventQueue('x_hsb11_mss_c_proc.el_custody_swift_reje', TradeRecord);
                    TradeRecord.swift_attribute_sync = "Attribute Sync is in progress";
                    TradeRecord.update();
                    return "queueTriggered";


                }
            }
        } catch (e) {
            gs.info("unexpected error occured:" + e);
        }
    },

    PositionDataForTrade: function() {
        try {
            var sysidTrade = this.getParameter("sysparm_id");
            var attributeTrade = this.getParameter("sysparm_attribute_sync");

            if (attributeTrade == "Attribute Sync is in progress") {
                return "Attribute Sync is in progress";
            }
            var TradeRecord = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
            TradeRecord.addQuery("sys_id", sysidTrade);
            TradeRecord.query();
            if (TradeRecord.next()) {

                if (TradeRecord.securities_account == '' || TradeRecord.security_id == '') {
                    return "security account or security id is empty";
                } else {
                    gs.eventQueue('x_hsb11_mss_c_proc.el_custody_detail_pos', TradeRecord);
                    TradeRecord.position_attribute_sync = "Attribute Sync is in progress";
                    TradeRecord.update();
                    return "queueTriggered";
                }


            }
        } catch (e) {
            gs.info("unexpected error occured:" + e);
        }
    },

    PositionDataForTask: function() {
        try {
            var sysidTask = this.getParameter("sysparm_id");
            var attributeTrade = this.getParameter("sysparm_attribute_sync");
            if (attributeTrade == "Attribute Sync is in progress") {
                return "Attribute Sync is in progress";
            }
            var taskRecord = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            taskRecord.addQuery("sys_id", sysidTask);
            taskRecord.query();
            if (taskRecord.next()) {

                if (taskRecord.trade_id.securities_account == '' || taskRecord.trade_id.security_id == '') {
                    return "security account or security id is empty";
                } else {
                    gs.eventQueue('x_hsb11_mss_c_proc.el_custody_detail_pos', taskRecord);
                    taskRecord.position_attribute_sync = "Attribute Sync is in progress";
                    taskRecord.update();
                    return "queueTriggered";
                }

            }
        } catch (e) {
            gs.info("unexpected error occured:" + e);
        }
    },
    type: 'getSwiftPosDataUIAction'
});
